public sealed class Hud06BProbe:MonoBehaviour{
const string Root="Docs/Measurements/2026-10-02-hud-06b/";RailwayOverview v;RailwayServicePanel s;
void Check(bool ok,string why){if(!ok)throw new Exception(why);}
UnityEngine.UI.Button B(string cmd)=>s.Actions.Single(a=>a.Command==cmd).Button;
